for h in dep.egress.svc.cluster.local other.egress.svc.cluster.local 10.96.151.61; do
  wget -q -T 4 -O /dev/null "http://$h" && echo "$h -> HTTP_OK (200)" || { wget --spider -T 4 -O /dev/null "http://$h" >/dev/null 2>&1 && echo "$h -> DENIED/REFUSED"; }
done' 2>&1
echo "=== pod status ==="; kubectl get pod -n egress app,dep 2>&1"}

